-- Vansvriksh initial relational schema.
-- IDs are generated by the API as UUIDs. Timestamps are UTC ISO-8601 strings.
PRAGMA foreign_keys = ON;

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  identity_provider TEXT NOT NULL DEFAULT 'google',
  provider_subject TEXT NOT NULL,
  email TEXT NOT NULL,
  display_name TEXT NOT NULL,
  avatar_url TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(identity_provider, provider_subject)
);

CREATE TABLE families (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),
  owner_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  privacy TEXT NOT NULL DEFAULT 'private' CHECK(privacy IN ('private')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE family_members (
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  role TEXT NOT NULL CHECK(role IN ('owner', 'admin', 'editor', 'viewer')),
  joined_at TEXT NOT NULL,
  PRIMARY KEY (family_id, user_id)
);

CREATE UNIQUE INDEX one_owner_role_per_family
  ON family_members(family_id) WHERE role = 'owner';

CREATE TABLE persons (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  given_name TEXT NOT NULL CHECK(length(trim(given_name)) BETWEEN 1 AND 120),
  middle_name TEXT,
  family_name TEXT,
  display_name TEXT,
  gender TEXT CHECK(gender IS NULL OR gender IN ('female', 'male', 'non_binary', 'unspecified')),
  life_status TEXT NOT NULL DEFAULT 'alive' CHECK(life_status IN ('alive', 'deceased')),
  birth_date_kind TEXT NOT NULL DEFAULT 'unknown'
    CHECK(birth_date_kind IN ('exact', 'year', 'approximate_year', 'range', 'unknown')),
  birth_exact_date TEXT,
  birth_year INTEGER,
  birth_range_start_year INTEGER,
  birth_range_end_year INTEGER,
  birth_original_text TEXT,
  death_date_kind TEXT NOT NULL DEFAULT 'unknown'
    CHECK(death_date_kind IN ('exact', 'year', 'approximate_year', 'range', 'unknown')),
  death_exact_date TEXT,
  death_year INTEGER,
  death_range_start_year INTEGER,
  death_range_end_year INTEGER,
  death_original_text TEXT,
  biography TEXT,
  created_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(id, family_id),
  CHECK(birth_range_start_year IS NULL OR birth_range_end_year IS NULL OR birth_range_start_year <= birth_range_end_year),
  CHECK(death_range_start_year IS NULL OR death_range_end_year IS NULL OR death_range_start_year <= death_range_end_year),
  CHECK(life_status = 'alive' OR death_date_kind <> 'unknown' OR death_original_text IS NULL)
);

CREATE INDEX persons_by_family_name ON persons(family_id, family_name, given_name);
CREATE INDEX persons_by_family_status ON persons(family_id, life_status);

CREATE TABLE relationships (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  from_person_id TEXT NOT NULL,
  to_person_id TEXT NOT NULL,
  relationship_type TEXT NOT NULL CHECK(relationship_type IN (
    'biological_parent', 'adoptive_parent', 'step_parent',
    'spouse', 'partner', 'sibling'
  )),
  metadata_json TEXT,
  created_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  CHECK(from_person_id <> to_person_id),
  FOREIGN KEY(from_person_id, family_id) REFERENCES persons(id, family_id) ON DELETE CASCADE,
  FOREIGN KEY(to_person_id, family_id) REFERENCES persons(id, family_id) ON DELETE CASCADE,
  UNIQUE(family_id, from_person_id, to_person_id, relationship_type)
);

CREATE INDEX relationships_from_person ON relationships(family_id, from_person_id);
CREATE INDEX relationships_to_person ON relationships(family_id, to_person_id);

CREATE TABLE invitations (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  inviter_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  invitee_email TEXT,
  invite_code_hash TEXT NOT NULL UNIQUE,
  offered_role TEXT NOT NULL CHECK(offered_role IN ('admin', 'editor', 'viewer')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'accepted', 'revoked', 'expired')),
  expires_at TEXT NOT NULL,
  accepted_at TEXT,
  revoked_at TEXT,
  created_at TEXT NOT NULL
);

CREATE INDEX invitations_by_family_status ON invitations(family_id, status);

CREATE TABLE media (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  person_id TEXT,
  object_key TEXT NOT NULL UNIQUE,
  media_type TEXT NOT NULL,
  content_type TEXT NOT NULL,
  byte_size INTEGER NOT NULL CHECK(byte_size > 0),
  metadata_json TEXT,
  uploaded_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY(person_id, family_id) REFERENCES persons(id, family_id) ON DELETE SET NULL
);

CREATE TABLE historical_sources (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  person_id TEXT NOT NULL,
  source_type TEXT NOT NULL CHECK(source_type IN (
    'oral_history', 'relative_recollection', 'photo', 'document',
    'government_record', 'temple_record', 'other'
  )),
  description TEXT NOT NULL,
  claim_text TEXT,
  media_id TEXT REFERENCES media(id) ON DELETE SET NULL,
  contributed_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY(person_id, family_id) REFERENCES persons(id, family_id) ON DELETE CASCADE
);

CREATE INDEX historical_sources_by_person ON historical_sources(family_id, person_id);

CREATE TABLE tree_layouts (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  layout_type TEXT NOT NULL CHECK(layout_type IN ('generation', 'ancestor', 'descendant')),
  focus_person_id TEXT,
  configuration_json TEXT NOT NULL DEFAULT '{}',
  created_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY(focus_person_id, family_id) REFERENCES persons(id, family_id) ON DELETE SET NULL
);

CREATE TABLE share_links (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  scope_type TEXT NOT NULL CHECK(scope_type IN ('family', 'branch')),
  focus_person_id TEXT,
  permission TEXT NOT NULL DEFAULT 'viewer' CHECK(permission = 'viewer'),
  expires_at TEXT,
  revoked_at TEXT,
  created_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY(focus_person_id, family_id) REFERENCES persons(id, family_id) ON DELETE SET NULL,
  CHECK((scope_type = 'family' AND focus_person_id IS NULL) OR
        (scope_type = 'branch' AND focus_person_id IS NOT NULL))
);

CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  entity_type TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  action TEXT NOT NULL,
  change_summary TEXT,
  created_at TEXT NOT NULL
);

CREATE INDEX audit_logs_by_family_time ON audit_logs(family_id, created_at DESC);

-- A deceased person's profile is immutable even if a future API path is implemented
-- incorrectly. Relationship records remain independently mutable.
CREATE TRIGGER deceased_person_profile_immutable
BEFORE UPDATE OF
  given_name, middle_name, family_name, display_name, gender, life_status,
  birth_date_kind, birth_exact_date, birth_year, birth_range_start_year,
  birth_range_end_year, birth_original_text, death_date_kind, death_exact_date,
  death_year, death_range_start_year, death_range_end_year, death_original_text,
  biography
ON persons
WHEN OLD.life_status = 'deceased'
BEGIN
  SELECT RAISE(ABORT, 'deceased_person_profile_immutable');
END;

CREATE TRIGGER deceased_person_delete_forbidden
BEFORE DELETE ON persons
WHEN OLD.life_status = 'deceased'
BEGIN
  SELECT RAISE(ABORT, 'deceased_person_delete_forbidden');
END;
